code.css:
:root{--ink:#232019;--ink-2:#4a453c;--paper:#f5f2ea;--paper-2:#eae4d8;--line:#cbc4b4;--line-strong:#b0a795;--accent:#9e3b2c;--accent-ink:#7d2c20;--radius:2px;--wrap:1160px;--pad:24px;}
*{box-sizing:border-box;}
body{margin:0;background:var(--paper);color:var(--ink);font-family:"Helvetica Neue",Arial,"PingFang SC","Hiragino Sans GB","Microsoft YaHei",sans-serif;font-size:16px;line-height:1.75;font-variant-numeric:tabular-nums;}
h1,h2,h3{margin:0 0 16px;font-weight:700;line-height:1.2;letter-spacing:-0.01em;}
h1{font-size:clamp(28px,5vw,52px);line-height:1.12;}
h2{font-size:clamp(22px,3.2vw,34px);}
h3{font-size:19px;margin-bottom:8px;}
p{margin:0 0 16px;max-width:38em;}
p:last-child{margin-bottom:0;}
ul,ol{margin:0;padding:0;list-style:none;}
a{color:inherit;text-decoration:none;}
.textlink{color:var(--accent-ink);border-bottom:1px solid var(--line-strong);padding-bottom:2px;}
.textlink:hover{border-bottom-color:var(--accent-ink);}
a:focus-visible,button:focus-visible{outline:2px solid var(--accent);outline-offset:3px;}
.wrap{max-width:var(--wrap);margin:0 auto;padding:0 var(--pad);}
.measure{max-width:38em;}
.lede{font-size:clamp(17px,1.9vw,20px);line-height:1.65;color:var(--ink-2);max-width:34em;}
.note{margin:18px 0 0;font-size:14px;line-height:1.7;color:var(--ink-2);max-width:38em;}
.section{padding:60px 0;}
.section--tight{padding:44px 0;}
.section--tint{background:var(--paper-2);}
.section--dark{background:var(--ink);color:#f3f0e7;}
.section--dark p{color:#e0dbcd;}
.section--dark .lede{color:#ded9cb;}
.section--dark .spec dt,.section--dark .spec dd{border-bottom-color:#4b4536;}
.section--dark .spec dt{color:#c6bda9;}
.section--line{border-top:1px solid var(--line);}
.band{font-size:clamp(23px,3.6vw,38px);line-height:1.28;max-width:20em;margin-bottom:20px;}
.site-header{background:var(--paper);border-bottom:1px solid var(--line);}
.site-header__inner{display:flex;align-items:center;gap:24px;min-height:66px;}
.brand{font-size:18px;font-weight:700;letter-spacing:0.02em;}
.site-nav{display:flex;gap:26px;margin-left:auto;font-size:15px;color:var(--ink-2);}
.site-nav a{padding:4px 0;border-bottom:1px solid transparent;}
.site-nav a:hover{color:var(--ink);border-bottom-color:var(--line-strong);}
.btn{display:inline-flex;align-items:center;gap:10px;padding:12px 22px;border:1px solid var(--ink);border-radius:var(--radius);background:var(--ink);color:#f7f4ec;font-size:15px;font-weight:700;line-height:1.2;}
.btn--accent{background:var(--accent);border-color:var(--accent);color:#fffefb;font-size:16px;padding:14px 26px;}
.hero{padding:64px 0 56px;border-bottom:1px solid var(--line);}
.hero__inner{display:grid;grid-template-columns:1.45fr 1fr;gap:48px;align-items:end;}
.hero__title{max-width:10em;margin-bottom:20px;}
.hero__act{display:flex;flex-direction:column;gap:14px;align-items:flex-start;}
.mail-line{display:flex;align-items:center;gap:8px;margin:0;font-size:15px;color:var(--ink-2);}
.section--dark .mail-line{color:#ded9cb;}
.rows{margin-top:28px;border-top:1px solid var(--line);}
.row{display:grid;grid-template-columns:200px 1fr auto;gap:28px;align-items:baseline;padding:24px 0;border-bottom:1px solid var(--line);}
.row p{margin:0;}
.row__name{font-size:18px;font-weight:700;}
.row__body p{margin-bottom:10px;}
.row__body p:last-child{margin-bottom:0;}
.row__act{align-self:start;}
.trio{display:grid;grid-template-columns:repeat(3,1fr);margin-top:28px;border-top:1px solid var(--line);}
.trio__item{padding:26px 28px 6px 0;}
.trio__item + .trio__item{border-left:1px solid var(--line);padding-left:28px;}
.trio__item p{font-size:15px;color:var(--ink-2);margin:0;}
.grid{display:grid;gap:48px;}
.grid--split{grid-template-columns:1.3fr 1fr;}
.grid--split-rev{grid-template-columns:1fr 1.3fr;}
.grid--2{grid-template-columns:1fr 1fr;}
.spec{margin:0;display:grid;grid-template-columns:118px 1fr;}
.spec dt,.spec dd{margin:0;padding:12px 0;border-bottom:1px solid var(--line);}
.spec dt{font-size:14px;color:var(--ink-2);}
.spec dd{font-size:16px;}
.list{border-top:1px solid var(--line);}
.list li{padding:12px 0;border-bottom:1px solid var(--line);font-size:16px;}
.steps{margin-top:28px;border-top:1px solid var(--line);}
.steps li{padding:22px 0;border-bottom:1px solid var(--line);}
.steps h3{margin-bottom:6px;}
.steps p{margin:0;color:var(--ink-2);}
.table-scroll{margin:20px 0 0;}
.table{width:100%;border-collapse:collapse;font-size:15px;}
.table th,.table td{text-align:left;padding:14px 18px 14px 0;border-bottom:1px solid var(--line);vertical-align:top;}
.table th{font-size:13px;letter-spacing:0.08em;font-weight:700;color:var(--ink-2);border-bottom:1px solid var(--ink);}
.qa{margin-top:28px;border-top:1px solid var(--line);}
.qa dt{padding:22px 0 6px;font-size:17px;font-weight:700;}
.qa dd{margin:0;padding:0 0 22px;max-width:38em;border-bottom:1px solid var(--line);color:var(--ink-2);}
.schematic{margin:0;padding:24px;border:1px solid var(--line);background:#fffdf7;}
.schematic figcaption{margin-top:16px;font-size:13px;line-height:1.6;color:var(--ink-2);}
.section--dark .schematic{background:#302c23;border-color:#5c5545;}
.section--dark .schematic figcaption{color:#c6bda9;}
.sch-drawer{position:relative;height:160px;}
.sch-drawer__sleeve{position:absolute;inset:0;border:1px solid var(--ink-2);background:var(--paper-2);}
.sch-drawer__tray{position:absolute;inset:18px 22px 18px 26%;border:1px solid var(--accent);background:#fffdf7;}
.sch-tray{display:flex;gap:18px;height:160px;padding:20px;border:1px solid var(--ink-2);background:var(--paper-2);}
.sch-tray__cavity{flex:1 1 0%;border:1px dashed var(--accent);border-radius:46% / 38%;background:#fffdf7;}
.sch-flute{height:40px;border-top:1px solid #8c8570;border-bottom:1px solid #8c8570;background:repeating-linear-gradient(90deg,#8c8570 0,#8c8570 1px,transparent 1px,transparent 9px);}
.band__body{margin-top:28px;}
.inquiry-block h2{margin-bottom:14px;}
.site-footer{background:var(--ink);color:#f3f0e7;padding:52px 0 30px;}
.site-footer__inner{display:grid;grid-template-columns:1.4fr 1.2fr 0.8fr;gap:36px;}
.footer-brand{margin:0 0 10px;font-size:18px;font-weight:700;}
.footer-desc{margin:0;max-width:28em;font-size:14px;color:#c6bda9;}
.footer-label{margin:0 0 10px;font-size:12px;letter-spacing:0.1em;color:#b3ab97;}
.footer-mail{margin:0 0 8px;font-size:16px;}
.footer-nav{display:flex;flex-direction:column;gap:8px;font-size:15px;}
.footer-nav a{align-self:flex-start;padding-bottom:1px;color:#e6e1d4;border-bottom:1px solid transparent;}
.footer-nav a:hover{border-bottom-color:#6f6754;}
.footer-note{margin:36px 0 0;padding-top:18px;border-top:1px solid #423c2f;font-size:13px;color:#b3ab97;}
@media (max-width:820px){.site-header__inner{flex-wrap:wrap;gap:8px 16px;padding:10px 0;min-height:0;}
.site-nav{order:3;width:100%;margin-left:0;gap:20px;font-size:14px;}
.btn{padding:11px 18px;font-size:14px;}
.btn--accent{padding:12px 20px;font-size:15px;}}
@media (max-width:768px){.grid{gap:28px;}
.grid--split,.grid--split-rev,.grid--2{grid-template-columns:1fr;}
.hero{padding:44px 0 40px;}
.hero__inner{grid-template-columns:1fr;gap:26px;align-items:start;}
.hero__title{max-width:100%;}
.section{padding:44px 0;}
.section--tight{padding:32px 0;}
.row{grid-template-columns:1fr;gap:10px;padding:20px 0;}
.trio{grid-template-columns:1fr;}
.trio__item{padding:20px 0;}
.trio__item + .trio__item{border-left:0;border-top:1px solid var(--line);padding-left:0;}
.site-footer__inner{grid-template-columns:1fr;gap:26px;}}
@media (max-width:640px){.table{font-size:13.5px;}
.table th,.table td{padding:12px 10px 12px 0;}}
@media (max-width:520px){.spec{grid-template-columns:1fr;}
.spec dt{padding-bottom:0;border-bottom:0;}
.spec dd{padding-top:4px;}
.sch-tray{gap:12px;padding:14px;height:140px;}
.sch-drawer{height:140px;}}
